def _normalized(path):
    if isinstance(path, int):
        return None
    try:
        value = os.fsdecode(path)
    except TypeError:
        return None
    if not os.path.isabs(value):
        value = os.path.join(os.getcwd(), value)
    return os.path.normpath(value)

